// supabase/functions/_shared/state-of-calls/synthetic.ts
//
// SYNTHETIC SAMPLE DATA - for design, demos and tests only. Never real businesses, never real numbers.
// Deterministic (seeded) so the sample edition is byte-for-byte reproducible.
// Any edition built from this module MUST be labelled synthetic (see SYNTHETIC_NOTICE).

import type { OrgFacts } from "./aggregate.ts";

export const SYNTHETIC_NOTICE =
  "SYNTHETIC SAMPLE DATA. Every number on this page was generated by a script for design and testing purposes. It does not describe any real business, region or period.";

export function mulberry32(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Per-trade monthly demand shape (index 0 = Jan), 1.0 = average. */
const SHAPE: Record<string, number[]> = {
  hvac: [1.15, 1.0, 0.8, 0.75, 0.9, 1.2, 1.45, 1.4, 1.0, 0.8, 0.8, 1.05],
  plumbing: [1.2, 1.05, 0.95, 0.9, 0.9, 0.95, 1.0, 0.95, 0.95, 0.95, 1.0, 1.2],
  electrical: [0.95, 0.95, 1.0, 1.0, 1.05, 1.1, 1.1, 1.05, 1.0, 1.0, 0.95, 0.9],
  "pest-control": [0.6, 0.7, 0.9, 1.2, 1.4, 1.5, 1.4, 1.2, 1.0, 0.8, 0.65, 0.6],
  roofing: [0.7, 0.7, 0.9, 1.1, 1.2, 1.2, 1.15, 1.2, 1.15, 1.1, 0.9, 0.7],
  locksmith: Array(12).fill(1),
};
const MIX: [string, number][] = [["hvac", 22], ["plumbing", 18], ["electrical", 14], ["pest-control", 12], ["roofing", 10], ["locksmith", 4]];
const REGIONS: [string, number][] = [["south", 40], ["west", 25], ["midwest", 20], ["northeast", 15]];
const LANGS: [string, number][] = [["english", 88], ["spanish", 9], ["portuguese", 1.5], ["vietnamese", 1.5]];

export function generateSyntheticOrgs(seed = 20260101): OrgFacts[] {
  const rnd = mulberry32(seed);
  const norm = () => { let s = 0; for (let i = 0; i < 6; i++) s += rnd(); return (s - 3) / Math.sqrt(0.5); };
  const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
  const pickW = (list: [string, number][]) => {
    const total = list.reduce((s, x) => s + x[1], 0);
    let r = rnd() * total;
    for (const [k, w] of list) { if ((r -= w) <= 0) return k; }
    return list[0][0];
  };
  const orgs: OrgFacts[] = [];
  let id = 0;
  for (const [trade, n] of MIX) {
    for (let i = 0; i < n; i++, id++) {
      const size = trade === "pest-control" && i === 0 ? 9000 : Math.round(clamp(900 * Math.exp(norm() * 0.5), 250, 3500)); // one dominant pest-control org
      const answer = clamp(0.84 + norm() * 0.05, 0.6, 0.99);
      const hasHours = rnd() > 0.15;
      const shape = SHAPE[trade];
      const calls = shape.map((f) => Math.max(1, Math.round((size / 12) * f * (0.9 + rnd() * 0.2))));
      const missed = calls.map((c) => Math.round(c * (1 - answer) * (0.9 + rnd() * 0.2)));
      const lang = pickW(LANGS);
      const langKnown = calls.map((c) => Math.round(c * 0.9));
      const total = langKnown.reduce((s, x) => s + x, 0);
      const spanishShare = lang === "spanish" ? 0.2 : 0.07;
      const lang_counts: Record<string, number> = { english: Math.round(total * (1 - spanishShare - 0.01)), spanish: Math.round(total * spanishShare) };
      if (lang === "portuguese" || lang === "vietnamese") lang_counts[lang] = Math.round(total * 0.012);
      const ah = clamp(0.28 + norm() * 0.05, 0.1, 0.5);
      const tickBase = { hvac: 480, plumbing: 360, electrical: 340, "pest-control": 190, roofing: 2400, locksmith: 150 }[trade] ?? 300;
      const jobs = Math.round(size * 0.12);
      orgs.push({
        trade, region: pickW(REGIONS),
        calls, missed,
        hours_eligible: hasHours ? [...calls] : calls.map(() => 0),
        after_hours: hasHours ? calls.map((c) => Math.round(c * ah)) : calls.map(() => 0),
        emergency: calls.map((c) => Math.round(c * clamp(0.1 + norm() * 0.03, 0.01, 0.3))),
        booked: calls.map((c, m) => Math.round((c - missed[m]) * clamp(0.43 + norm() * 0.06, 0.1, 0.9))),
        lang_known: langKnown, lang_counts,
        lead_resp_n: Math.round(size * 0.2), lead_resp_median_min: Math.max(1, Math.round(9 * Math.exp(norm() * 0.6))),
        ticket_jobs: jobs, ticket_sum: jobs * tickBase * Math.exp(norm() * 0.15),
      });
    }
  }
  return orgs;
}
